"""User management API module (in-memory).

Implements CRUD + search per provided specification using a minimal HTTP-like
router abstraction (no external web frameworks required).

Public entrypoint: `app` (instance of UserAPI) with `handle(method, path, query, json_body)`.
"""

from __future__ import annotations

from dataclasses import dataclass, asdict
from datetime import datetime, timezone
import re
from typing import Any, Dict, List, Optional, Tuple


EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def normalize_email(email: str) -> str:
    return email.strip().lower()


@dataclass
class User:
    id: int
    email: str
    full_name: str
    status: str
    created_at: str
    updated_at: str

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class HTTPError(Exception):
    def __init__(self, status: int, code: str, detail: str, fields: Optional[Dict[str, str]] = None):
        super().__init__(detail)
        self.status = status
        self.code = code
        self.detail = detail
        self.fields = fields or {}

    def to_response(self) -> Tuple[int, Dict[str, Any]]:
        payload: Dict[str, Any] = {"error": {"code": self.code, "detail": self.detail}}
        if self.fields:
            payload["error"]["fields"] = self.fields
        return self.status, payload


class UserStore:
    def __init__(self):
        self._users: Dict[int, User] = {}
        self._email_to_id: Dict[str, int] = {}
        self._next_id = 1

    def create(self, email: str, full_name: str, status: str) -> User:
        email_n = normalize_email(email)
        if email_n in self._email_to_id:
            raise HTTPError(409, "conflict", "email already exists")
        uid = self._next_id
        self._next_id += 1
        ts = now_iso()
        user = User(id=uid, email=email_n, full_name=full_name, status=status, created_at=ts, updated_at=ts)
        self._users[uid] = user
        self._email_to_id[email_n] = uid
        return user

    def get(self, user_id: int) -> User:
        user = self._users.get(user_id)
        if not user:
            raise HTTPError(404, "not_found", "user not found")
        return user

    def patch(self, user_id: int, *, full_name: Optional[str] = None, status: Optional[str] = None) -> User:
        user = self.get(user_id)
        changed = False
        if full_name is not None:
            user.full_name = full_name
            changed = True
        if status is not None:
            user.status = status
            changed = True
        if changed:
            user.updated_at = now_iso()
        return user

    def list(
        self,
        *,
        query: Optional[str] = None,
        status: Optional[str] = None,
        sort: str = "id",
        order: str = "asc",
        limit: int = 50,
        offset: int = 0,
    ) -> Tuple[int, List[User]]:
        users = list(self._users.values())
        if status is not None:
            users = [u for u in users if u.status == status]
        if query:
            q = query.lower()
            users = [u for u in users if q in u.email.lower() or q in u.full_name.lower()]

        reverse = order.lower() == "desc"
        if sort not in {"id", "email", "full_name", "status", "created_at", "updated_at"}:
            raise HTTPError(400, "validation_error", "invalid sort field", {"sort": "unsupported field"})

        users.sort(key=lambda u: getattr(u, sort), reverse=reverse)
        total = len(users)
        users = users[offset : offset + limit]
        return total, users


def _require_object(body: Any) -> Dict[str, Any]:
    if not isinstance(body, dict):
        raise HTTPError(400, "validation_error", "invalid JSON body", {"body": "must be an object"})
    return body


def _validate_email(email: Any, fields: Dict[str, str]):
    if not isinstance(email, str) or not email.strip():
        fields["email"] = "required"
        return
    if not EMAIL_RE.match(email.strip()):
        fields["email"] = "invalid email"


def _validate_full_name(full_name: Any, fields: Dict[str, str], required: bool):
    if full_name is None:
        if required:
            fields["full_name"] = "required"
        return
    if not isinstance(full_name, str) or not full_name.strip():
        fields["full_name"] = "must be a non-empty string"


def _validate_status(status: Any, fields: Dict[str, str], required: bool):
    if status is None:
        if required:
            fields["status"] = "required"
        return
    if not isinstance(status, str):
        fields["status"] = "must be a string"
        return
    if status not in {"active", "disabled"}:
        fields["status"] = "must be one of: active, disabled"


class UserAPI:
    """Tiny request handler with endpoints:

    - POST /users
    - GET /users/{id}
    - PATCH /users/{id}
    - GET /users
    """

    def __init__(self, store: Optional[UserStore] = None):
        self.store = store or UserStore()

    def handle(
        self,
        method: str,
        path: str,
        *,
        query: Optional[Dict[str, str]] = None,
        json_body: Any = None,
    ) -> Tuple[int, Dict[str, Any]]:
        try:
            return self._handle(method.upper(), path, query or {}, json_body)
        except HTTPError as e:
            return e.to_response()

    def _handle(self, method: str, path: str, query: Dict[str, str], body: Any) -> Tuple[int, Dict[str, Any]]:
        if path == "/users" and method == "POST":
            data = _require_object(body)
            fields: Dict[str, str] = {}
            _validate_email(data.get("email"), fields)
            _validate_full_name(data.get("full_name"), fields, required=True)
            _validate_status(data.get("status"), fields, required=True)
            if fields:
                raise HTTPError(400, "validation_error", "invalid request body", fields)
            user = self.store.create(data["email"], data["full_name"].strip(), data["status"])
            return 201, {"data": user.to_dict()}

        if path == "/users" and method == "GET":
            fields: Dict[str, str] = {}
            status = query.get("status")
            if status is not None:
                _validate_status(status, fields, required=False)
            q = query.get("query")
            sort = query.get("sort", "id")
            order = query.get("order", "asc")

            def parse_int(name: str, default: int) -> int:
                if name not in query:
                    return default
                try:
                    v = int(query[name])
                except Exception:
                    fields[name] = "must be an integer"
                    return default
                if v < 0:
                    fields[name] = "must be >= 0"
                return v

            limit = parse_int("limit", 50)
            offset = parse_int("offset", 0)
            if limit == 0:
                fields["limit"] = "must be > 0"
            if order.lower() not in {"asc", "desc"}:
                fields["order"] = "must be asc or desc"
            if fields:
                raise HTTPError(400, "validation_error", "invalid query parameters", fields)
            total, users = self.store.list(query=q, status=status, sort=sort, order=order, limit=limit, offset=offset)
            return 200, {"data": [u.to_dict() for u in users], "meta": {"total": total, "limit": limit, "offset": offset}}

        m = re.match(r"^/users/(\d+)$", path)
        if m:
            user_id = int(m.group(1))
            if method == "GET":
                user = self.store.get(user_id)
                return 200, {"data": user.to_dict()}
            if method == "PATCH":
                data = _require_object(body)
                fields: Dict[str, str] = {}
                if "email" in data:
                    fields["email"] = "email is immutable"
                if "full_name" in data:
                    _validate_full_name(data.get("full_name"), fields, required=False)
                if "status" in data:
                    _validate_status(data.get("status"), fields, required=False)
                if not any(k in data for k in ("full_name", "status")) and "email" not in data:
                    fields["body"] = "at least one of: full_name, status"
                if fields:
                    raise HTTPError(400, "validation_error", "invalid request body", fields)
                user = self.store.patch(user_id, full_name=(data.get("full_name").strip() if "full_name" in data else None), status=(data.get("status") if "status" in data else None))
                return 200, {"data": user.to_dict()}

        raise HTTPError(404, "not_found", "endpoint not found")


app = UserAPI()

